    auto nxt = [&](){ s ^= s<<13; s ^= s>>7; s ^= s<<17; return s; };
    for (int i=0;i<40000;i++){
        uint64_t h = nxt() % 20000000000000ULL; // n/2 up to 1e13
        double d = (double)h * 0.5;
        add(d); add(-d);
    }
    // 4. 1e-5 .. 1e-3 range
    for (int i=1;i<=20000;i++){ add(1e-5 + (double)i*(1e-3-1e-5)/20000.0); }
    for (int i=1;i<=2000;i++){ add((double)i*1e-6); add((double)i*1e-7); }
    // 5. tie stressors: d.dddddd5 * 10^k patterns
    for (int lead=100000; lead<1000000; lead+=7777){
        for (int k=-12;k<=12;k++){
            // value = (lead*10 + 5) * 10^k  -> exact tie in decimal, not necessarily in binary
            char buf[64]; snprintf(buf,sizeof buf,"%d5e%d", lead, k);
            add(strtod(buf,nullptr));
        }
    }
    // 6. random full-range bit patterns (finite only)
    for (int i=0;i<60000;i++){
        uint64_t b = nxt();
        uint64_t expo = (b>>52)&0x7ff;
        if (expo==0x7ff) b &= ~(1ULL<<62); // avoid inf/nan
        addbits(b);
    }
    // 7. specials
    addbits(0x7ff0000000000000ULL); addbits(0xfff0000000000000ULL);
    addbits(0x7ff8000000000000ULL); addbits(0xfff8000000000000ULL);
    addbits(0x0000000000000001ULL); addbits(0x000fffffffffffffULL);
    addbits(0x7fefffffffffffffULL); addbits(0xffefffffffffffffULL);

    for (uint64_t b : vals){
        double d; std::memcpy(&d,&b,8);
