// std-only reimplementation of `std::cout << (double)x` with a default-configured
// ostream (== printf("%.6g", x) in the "C" locale).
use std::io::{self, BufRead, Write};

// ---------- exact big decimal (base 1e9 limbs, little endian) ----------
const BASE: u64 = 1_000_000_000;
const POW5: [u64; 13] = [
    1, 5, 25, 125, 625, 3125, 15625, 78125, 390625, 1_953_125, 9_765_625, 48_828_125, 244_140_625,
];

struct BigDec {
    limbs: Vec<u64>,
}

impl BigDec {
    fn from_u64(mut v: u64) -> Self {
        let mut limbs = Vec::with_capacity(4);
        if v == 0 {
            limbs.push(0);
        }
        while v > 0 {
            limbs.push(v % BASE);
            v /= BASE;
        }
        BigDec { limbs }
    }
    fn mul_small(&mut self, m: u64) {
        let mut carry: u64 = 0;
        for l in self.limbs.iter_mut() {
            let cur = *l * m + carry;
            *l = cur % BASE;
            carry = cur / BASE;
        }
        while carry > 0 {
            self.limbs.push(carry % BASE);
            carry /= BASE;
        }
    }
    fn mul_pow2(&mut self, mut n: u32) {
        while n > 0 {
            let k = if n > 29 { 29 } else { n };
            self.mul_small(1u64 << k);
            n -= k;
        }
    }
    fn mul_pow5(&mut self, mut n: u32) {
        while n > 0 {
            let k = if n > 12 { 12 } else { n };
            self.mul_small(POW5[k as usize]);
            n -= k;
        }
    }
    /// Decimal digits, most significant first, no leading zeros ("0" for zero).
    fn to_digits(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.limbs.len() * 9);
        let n = self.limbs.len();
        let top = self.limbs[n - 1];
        if top == 0 && n == 1 {
            out.push(b'0');
            return out;
        }
        // top limb without leading zeros
        let mut buf = [0u8; 9];
        let mut t = top;
        let mut len = 0usize;
        while t > 0 {
            buf[len] = b'0' + (t % 10) as u8;
            t /= 10;
            len += 1;
        }
        for i in (0..len).rev() {
            out.push(buf[i]);
        }
        // remaining limbs, 9 digits each, zero padded
        for i in (0..n - 1).rev() {
            let mut v = self.limbs[i];
            let mut b = [b'0'; 9];
            let mut j = 9usize;
            while v > 0 {
                j -= 1;
                b[j] = b'0' + (v % 10) as u8;
                v /= 10;
            }
            out.extend_from_slice(&b);
        }
        out
    }
}

/// Byte-identical to `std::cout << x` for a default-configured std::ostream
/// (defaultfloat, precision 6, no showpoint, no showpos, "C" locale).
pub fn fmt_double_cout(x: f64) -> String {
    const P: usize = 6; // stream precision (significant digits)

    let bits = x.to_bits();
    let neg = (bits >> 63) != 0;
    let raw_exp = ((bits >> 52) & 0x7ff) as i32;
    let raw_man = bits & 0x000f_ffff_ffff_ffff;

    if raw_exp == 0x7ff {
        let body = if raw_man != 0 { "nan" } else { "inf" };
        return if neg {
            let mut s = String::from("-");
            s.push_str(body);
            s
        } else {
            String::from(body)
        };
    }
    if raw_exp == 0 && raw_man == 0 {
        return String::from(if neg { "-0" } else { "0" });
    }

    // |x| == m * 2^e exactly
    let (m, e): (u64, i32) = if raw_exp == 0 {
        (raw_man, -1074)
    } else {
        (raw_man | (1u64 << 52), raw_exp - 1075)
    };

    // exact decimal integer N and scale s with |x| == N * 10^(-s)
    let mut big = BigDec::from_u64(m);
    let scale: i32;
    if e >= 0 {
        big.mul_pow2(e as u32);
        scale = 0;
    } else {
        big.mul_pow5((-e) as u32);
        scale = -e;
    }
    let digits = big.to_digits();
    let l = digits.len() as i32;
    // decimal exponent of the leading digit: |x| == d.ddd... * 10^xexp
    let mut xexp = (l - 1) - scale;

    // round to P significant digits, round-half-to-even (glibc FE_TONEAREST)
    let mut sig: Vec<u8>;
    if digits.len() <= P {
        sig = digits;
        while sig.len() < P {
            sig.push(b'0');
        }
    } else {
        sig = digits[..P].to_vec();
        let half = digits[P];
        let more = digits[P + 1..].iter().any(|&c| c != b'0');
        let last_odd = (sig[P - 1] - b'0') % 2 == 1;
        let away = half > b'5' || (half == b'5' && (more || last_odd));
        if away {
            let mut i = P;
            loop {
                if i == 0 {
                    sig.insert(0, b'1');
                    sig.pop();
                    xexp += 1;
                    break;
                }
                i -= 1;
                if sig[i] == b'9' {
                    sig[i] = b'0';
                } else {
                    sig[i] += 1;
                    break;
                }
            }
        }
    }

    let mut out = String::with_capacity(24);
    if neg {
        out.push('-');
    }

    if xexp < -4 || xexp >= P as i32 {
        // style e, precision P-1, trailing zeros stripped
        out.push(sig[0] as char);
        let mut end = sig.len();
        while end > 1 && sig[end - 1] == b'0' {
            end -= 1;
        }
        if end > 1 {
            out.push('.');
            for &c in &sig[1..end] {
                out.push(c as char);
            }
        }
        out.push('e');
        out.push(if xexp < 0 { '-' } else { '+' });
        let ae = if xexp < 0 { -(xexp as i64) } else { xexp as i64 } as u64;
        let mut eb = [0u8; 20];
        let mut n = 0usize;
        let mut t = ae;
        if t == 0 {
            eb[0] = b'0';
            n = 1;
        }
        while t > 0 {
            eb[n] = b'0' + (t % 10) as u8;
            t /= 10;
            n += 1;
        }
        while n < 2 {
            eb[n] = b'0';
            n += 1;
        }
        for i in (0..n).rev() {
            out.push(eb[i] as char);
        }
    } else {
        // style f, precision P-1-xexp, trailing zeros stripped
        let mut frac: Vec<u8> = Vec::with_capacity(16);
        if xexp >= 0 {
            let k = xexp as usize; // 0..=P-1
            for &c in &sig[..=k] {
                out.push(c as char);
            }
            frac.extend_from_slice(&sig[k + 1..]);
        } else {
            out.push('0');
            for _ in 0..(-xexp - 1) {
                frac.push(b'0');
            }
            frac.extend_from_slice(&sig);
        }
        let mut end = frac.len();
        while end > 0 && frac[end - 1] == b'0' {
            end -= 1;
        }
        if end > 0 {
            out.push('.');
            for &c in &frac[..end] {
                out.push(c as char);
            }
        }
    }
    out
}

fn main() {
    let stdin = io::stdin();
    let out = io::stdout();
    let mut w = io::BufWriter::new(out.lock());
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let hex = line.split(' ').next().unwrap();
        if hex.len() != 16 {
            continue;
        }
        let bits = u64::from_str_radix(hex, 16).unwrap();
        let d = f64::from_bits(bits);
        writeln!(w, "{} {}", hex, fmt_double_cout(d)).unwrap();
    }
    w.flush().unwrap();
}
