// Alternative: derive %.6g from Rust's built-in {:.5e} (exact-precision) formatter.
use std::io::{self, BufRead, Write};

pub fn fmt_double_cout_std(x: f64) -> String {
    const P: usize = 6;
    if x.is_nan() { return if x.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if x.is_infinite() { return if x < 0.0 { "-inf".into() } else { "inf".into() }; }
    if x == 0.0 { return if x.is_sign_negative() { "-0".into() } else { "0".into() }; }
    let neg = x.is_sign_negative();
    let s = format!("{:.*e}", P - 1, x.abs());          // e.g. "1.23456e6", "9.99999e-5"
    let (mant, ex) = s.split_once('e').unwrap();
    let xexp: i32 = ex.parse().unwrap();
    let sig: Vec<u8> = mant.bytes().filter(|&c| c != b'.').collect();  // exactly P digits
    let mut out = String::new();
    if neg { out.push('-'); }
    if xexp < -4 || xexp >= P as i32 {
        out.push(sig[0] as char);
        let mut end = sig.len();
        while end > 1 && sig[end-1] == b'0' { end -= 1; }
        if end > 1 { out.push('.'); for &c in &sig[1..end] { out.push(c as char); } }
        out.push('e');
        out.push(if xexp < 0 { '-' } else { '+' });
        let ae = xexp.unsigned_abs();
        if ae < 10 { out.push('0'); }
        out.push_str(&ae.to_string());
    } else {
        let mut frac: Vec<u8> = Vec::new();
        if xexp >= 0 {
            let k = xexp as usize;
            for &c in &sig[..=k] { out.push(c as char); }
            frac.extend_from_slice(&sig[k+1..]);
        } else {
            out.push('0');
            for _ in 0..(-xexp - 1) { frac.push(b'0'); }
            frac.extend_from_slice(&sig);
        }
        let mut end = frac.len();
        while end > 0 && frac[end-1] == b'0' { end -= 1; }
        if end > 0 { out.push('.'); for &c in &frac[..end] { out.push(c as char); } }
    }
    out
}

fn main(){
    let si = io::stdin(); let so = io::stdout(); let mut w = io::BufWriter::new(so.lock());
    for line in si.lock().lines() { let line = line.unwrap();
        let hex = line.split(' ').next().unwrap(); if hex.len()!=16 { continue; }
        let d = f64::from_bits(u64::from_str_radix(hex,16).unwrap());
        writeln!(w,"{} {}",hex,fmt_double_cout_std(d)).unwrap(); }
    w.flush().unwrap();
}
